#!/usr/bin/env python3
# use the agent.py file to run the agent
import os
import argparse
from agentBaseline import AgentAIBaseline
from tqdm import tqdm
import pandas as pd
import json
import yaml
from time import time, sleep
from datetime import datetime

TIME_BETWEEN_SLEEP = 1800
MAX_ITERATIONS = 5  # Set the maximum number of iterations

def get_code(response):
    '''This method gets the program code generated by the prompt. 
       The generation often results in a markdown code block. 
       This method extracts the code from the markdown block and returns it as a string.'''
    # create a json object from the response
    # remove the first and the last line
    if response:
        mdCode = response.split('\n')
        mdCode = '\n'.join(mdCode)
    else:
        mdCode = ""
    return mdCode


def collect_tasks(file_path):
    df = pd.read_excel(file_path)
    #df = pd.read_csv(file_path)
    return df


def check_if_existing(row, df_generated_solutions,result_file_path):   

    if row["Task_Name"] in df_generated_solutions['Task_Name'].values:
        val = df_generated_solutions.loc[df_generated_solutions["Task_Name"].eq(row["Task_Name"]), "Generated_code"].iloc[0]
        if pd.isna(val) or val.strip() == "":
            df_generated_solutions = df_generated_solutions.loc[~df_generated_solutions["Task_Name"].eq(row["Task_Name"])].copy()
            print(f"Previous generation for task {row['Task_Name']} was empty. Regenerating...")
            df_generated_solutions.to_csv(result_file_path, mode='w', index=False)
            return df_generated_solutions, False
        else:
            return df_generated_solutions, True
        
    elif row["Task_Name"] not in df_generated_solutions['Task_Name'].values:
        return df_generated_solutions, False
    else:
        return df_generated_solutions, True
    


def generate_from_agent(df, df_generated_solutions, lang, model, role_description, result_file_path, server_url, api_key=""):
     
    num_rows = df.shape[0]
    prev_index = 0
    dir_path = f'output_baseline/agentic_individual_tasks/{model.replace("/", "_")}'

    time_round_elapsed = 0

    for index, row in df.iterrows():

        time_start = time()

        file_name_run = f'{lang}_{model.replace("/", "_")}_{row["Task_Name"].replace(" ","")}.xlsx'
        df_generated_solutions, result_exist = check_if_existing(row, df_generated_solutions,result_file_path)

        if not result_exist:
            agentProgrammer = AgentAIBaseline(server_address=server_url, 
                                        model_name=model,
                                        my_role=role_description,
                                        language=lang,
                                        api_key=api_key)

            responseProgrammer, attempts = agentProgrammer.start(MAX_ITERATIONS, row['Task_Description'])
            
            generated_solution = get_code(responseProgrammer)
            data = {
                'Task_Name': row["Task_Name"],
                'Language': lang,
                'Model': model,
                'Task_Description': row['Task_Description'],
                'Generated_code': generated_solution,
                'Attempts': attempts
            }
            df_generated_solutions = pd.concat([df_generated_solutions, pd.DataFrame([data])], ignore_index=True)
            if not os.path.exists(dir_path):
                os.mkdir(dir_path)
           
            agentProgrammer.save_to_excel(f'{dir_path}/{file_name_run}')
        else:
            print(f"Skipping already processed task: {row['Task_Name']}")
            prev_index += 1

        if (index + 1) % 5 == 0 or index + 1 == num_rows:
            current_time = datetime.now()
            formatted_string = current_time.strftime("%Y-%m-%d %H:%M:%S")

            print(f"Processed {index + 1}/{num_rows} tasks for {lang} using {model}\t{formatted_string}")
            subset = df_generated_solutions.iloc[prev_index:index + 1]
            if os.path.exists(result_file_path):
                subset.to_csv(result_file_path, mode='a', header=False, index=False)
            else:
                subset.to_csv(result_file_path, mode='a', index=False)
            prev_index = index + 1

            saved_df = pd.read_csv(result_file_path)
            print(f"Results saved. Total saved tasks: {len(saved_df)}/ {num_rows}")
        
        time_end = time()
        elapsed_time = time_end - time_start
        time_round_elapsed += elapsed_time

        if time_round_elapsed >= TIME_BETWEEN_SLEEP:
            print(f"Elapsed time for this round: {time_round_elapsed} seconds. Sleeping for 10 min to avoid server overload.")
            time_round_elapsed = 0
            sleep(600)
            

        
def read_settings(settings_file):

    with open(settings_file, 'r') as f:
        settings = yaml.safe_load(f)

    server_url = settings["server_url"] 
    models = settings["models"] 
    languages = settings["languages"] 
    generate_type = settings["generate_type"] 

    if "api_key" in settings.keys():
        api_key = settings["api_key"]
    else:
        api_key = ""

    return server_url, models, languages, generate_type, api_key


def main():
    # Parse command-line arguments

    parser = argparse.ArgumentParser()
    parser.add_argument('--settings_file', '-f', required=True)
    args = parser.parse_args()

    server_url, models, languages, _, api_key = read_settings(args.settings_file)
    
    #languages = ['C']

    for lang in languages:

        for model in models:

            print(f"Processing language: {lang}")
            print(f"Using model: {model}")
            
            role_description = f"You are a software that writes {lang} programs based on prompts. Provides only the code, no description."

            df_generated_solutions = pd.DataFrame(columns=['Task_Name','Language', 'Model', 'Task_Description', 'Solution', 'Generated_code', 'Attempts'])
            result_file_path = f"output_baseline/{lang}_{model.replace("/","_")}_baseline_generated_code.csv"

            if os.path.exists(result_file_path):
                df_generated_solutions = pd.read_csv(result_file_path)
                print(f"{result_file_path} exists. Loaded {len(df_generated_solutions)} previously saved tasks.")                
            else:
                df_generated_solutions = pd.DataFrame(columns=['Task_Name','Language', 'Model', 'Task_Description', 'Solution', 'Generated_code', 'Attempts'])

            df = collect_tasks(file_path=f"data/all_tasks.xlsx")

            generate_from_agent(df, df_generated_solutions, lang, model, role_description, result_file_path, server_url, api_key)
    
if __name__ == "__main__":
    main()
